# Verify by finding a path of length 4 to 1f0e3dad99
def find_path(adjacency, start, end):
    from collections import deque
    queue = deque([(start, [start])])
    visited = {start}
    while queue:
        node, path = queue.popleft()
        if node == end:
            return path
        for neighbor in adjacency.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))
    return None

path = find_path(adjacency, '1679091c5a', '1f0e3dad99')
print("Path from 1679091c5a to 1f0e3dad99:", path)
print("Path length:", len(path) - 1 if path else None)

